'use strict';
state.colors=atlasColors(null);
const colorPanel=document.createElement('section');colorPanel.className='panel colors-panel';
colorPanel.innerHTML=`<div class="section-heading"><span class="step">04</span><h2>图片配色</h2></div><p class="label-intro">选择背景与航线颜色，统计区会自动适配明暗与文字颜色。</p><div class="color-presets" role="group" aria-label="配色预设"></div><div class="color-fields"></div><p id="color-note" class="micro" role="status"></p><button type="button" id="colors-reset" class="text-button">恢复默认配色</button>`;
document.querySelector('.settings').insertBefore(colorPanel,document.querySelector('.settings .help'));
const colorPresets=[['深蓝金','#101c2a','#e8bf79'],['暖白蓝','#f3efe7','#28659c'],['松绿金','#122e2b','#e0b778'],['暮紫粉','#261d35','#ed9eae']];
for(const [name,background,route] of colorPresets){const b=document.createElement('button');b.type='button';b.className='color-preset';b.textContent=name;b.dataset.background=background;b.dataset.route=route;b.style.setProperty('--swatch-bg',background);b.style.setProperty('--swatch-route',route);b.addEventListener('click',()=>setAtlasColors({background,route}));colorPanel.querySelector('.color-presets').append(b);}
for(const [key,label] of [['background','地图背景'],['route','航线颜色']]){const row=document.createElement('div');row.className='color-field';row.innerHTML=`<label for="color-${key}">${label}</label><div><input type="color" id="color-${key}" aria-label="${label}"><input type="text" id="hex-${key}" aria-label="${label}十六进制色值" maxlength="7" spellcheck="false"></div>`;colorPanel.querySelector('.color-fields').append(row);row.querySelector('input[type=color]').addEventListener('change',e=>setAtlasColors({...state.colors,[key]:e.target.value}));row.querySelector('input[type=text]').addEventListener('change',e=>{if(!/^#[0-9a-f]{6}$/i.test(e.target.value)){e.target.setCustomValidity('请输入 # 加六位十六进制色值，例如 #101c2a');e.target.reportValidity();return;}e.target.setCustomValidity('');setAtlasColors({...state.colors,[key]:e.target.value});});}
function syncAtlasColorControls(){state.colors=atlasColors(state.colors);for(const key of ['background','route']){$('color-'+key).value=state.colors[key];$('hex-'+key).value=state.colors[key];$('hex-'+key).setCustomValidity('');}colorPanel.querySelectorAll('.color-preset').forEach(b=>{const selected=b.dataset.background===state.colors.background&&b.dataset.route===state.colors.route;b.setAttribute('aria-pressed',String(selected));});$('color-note').textContent=atlasContrast(state.colors.background,state.colors.route)<2?'当前航线与背景比较接近，建议加大明暗差，航线会更清晰。':'颜色自动保存，并同步到高清图片。';}
function setAtlasColors(value){state.colors=atlasColors(value);syncAtlasColorControls();regenerate();}
$('colors-reset').addEventListener('click',()=>setAtlasColors(null));syncAtlasColorControls();
